INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(50511, 'Psalms 76:2', 'Psalms', 76, 2, 'په اورشلیم کې ده خېمه د هغه استوګنځی یې د صهیون په غره کې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms76_verse_2.mp3', '', 1761754199, 1761754199),
(50512, 'Psalms 76:3', 'Psalms', 76, 3, 'تاوده غشي یې کړل مات په هغه ځای کې هم یې سپرونه، تورې او ټولې وسلې ماتې کړې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms76_verse_3.mp3', '', 1761754199, 1761754199),
(50513, 'Psalms 76:4', 'Psalms', 76, 4, 'ته څومره ډک یې له جلاله او له نوره خدایه! څومره له برمه ډک یې زیات له تلپاتې غرو نه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms76_verse_4.mp3', '', 1761754199, 1761754199),
(50514, 'Psalms 76:5', 'Psalms', 76, 5, 'د دښمن زړور خلک ټول تالا شول د مرګ په خوب باندې ویده شول هغوی نور یې نه لرله وسه چې لاسونه جګ کړي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms76_verse_5.mp3', '', 1761754199, 1761754199),
(50515, 'Psalms 76:6', 'Psalms', 76, 6, 'د یعقوب خدایه، تا چې کله ورټل هغوی د دوی اسونه او سواره شول په مرګ ویده', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms76_verse_6.mp3', '', 1761754199, 1761754199),
(50516, 'Psalms 76:7', 'Psalms', 76, 7, 'یوازې ستا نه وېرېدل په کار دي کله چې ته په قهر یې څوک درېدلی شي د ستا په مخکې؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms76_verse_7.mp3', '', 1761754199, 1761754199),
(50517, 'Psalms 76:8', 'Psalms', 76, 8, 'تا خپل قضاوت کړ د اسمان نه اعلان نو ځمکه وېرېدله او شوه خاموشه هغه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms76_verse_8.mp3', '', 1761754199, 1761754199),
(50518, 'Psalms 76:9', 'Psalms', 76, 9, 'کله چې ته خدایه راپورته قضاوت ته شولې چې د دنیا ټول مظلومان وژغورې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms76_verse_9.mp3', '', 1761754199, 1761754199),
(50519, 'Psalms 76:10', 'Psalms', 76, 10, 'د انسانانو قهر ګرځي سبب ستا د ثنا څوک چې ژوندي شول پاتې ستا له غضب هغوی به تا لره جشنونه نیسي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms76_verse_10.mp3', '', 1761754199, 1761754199),
(50520, 'Psalms 76:11', 'Psalms', 76, 11, 'خپل څښتن خدای ته ومنئ نذرونه او هغه ورکړئ خپل سوغاتونه راوړئ ای ټولو خلکو، چې اوسېږئ شاوخوا د هغه هغه دپاره چې دی ډېر هیبتناک', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms76_verse_11.mp3', '', 1761754199, 1761754199),
(50521, 'Psalms 76:12', 'Psalms', 76, 12, 'ماتوي هغه غرور د واکمنانو په پاچاهانو د نړۍ راولي سخته وېره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms76_verse_12.mp3', '', 1761754199, 1761754199),
(50522, 'Jeremiah 23:1', 'Jeremiah', 23, 1, 'مالِک خُدائ فرمائى چې، ”افسوس دے د قوم په شپونکو باندې څوک چې زما د څرن د ځائ ګډې تباه کوى او خوروى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah23_verse_1.mp3', '', 1761754199, 1761754199),
(50523, 'Jeremiah 23:2', 'Jeremiah', 23, 2, 'نو ځکه مالِک خُدائ، د بنى اِسرائيلو خُدائ پاک، دې شپونکو ته فرمائى چې، ”تاسو زما رمې خورې ورې کړې او د خپل ځان نه مو لرې شړلې دى او د هغوئ مو ښۀ خيال نۀ دے ساتلے، زۀ به تاسو له د دې بد کار سزا درکړم، مالِک خُدائ فرمائى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah23_verse_2.mp3', '', 1761754199, 1761754199),
(50524, 'Jeremiah 23:3', 'Jeremiah', 23, 3, 'زۀ به په خپله د خپلې رمې باقى پاتې شوى خلق د هغه ټولو مُلکونو نه راغونډ کړم کومو ته چې ما شړلى وُو او خپل وطن ته به يې واپس راولم. چرته چې به هغوئ مېوه ونيسى او د هغوئ شمېر به ډېر شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah23_verse_3.mp3', '', 1761754199, 1761754199),
(50525, 'Jeremiah 23:4', 'Jeremiah', 23, 4, 'زۀ به په هغوئ شپونکى مقرر کړم چې د هغوئ خيال وساتى، او هغوئ به نور د چا نه نۀ يريږى او نۀ به پرېشانه شى. او نۀ به يو ورک شى. ما مالِک خُدائ دا وفرمائيل.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah23_verse_4.mp3', '', 1761754199, 1761754199),
(50526, 'Jeremiah 23:5', 'Jeremiah', 23, 5, 'مالِک خُدائ فرمائى چې، ”هغه ورځې راتلونکې دى چې، زۀ به د داؤد په نسل کښې يوه صادقه څانګه راپورته کړم او بادشاه به يې کړم، او هغه به په هوښيارتيا سره حکومت کوى. او هغه به په مُلک کښې صداقت او اِنصاف قائم کړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah23_verse_5.mp3', '', 1761754199, 1761754199),
(50527, 'Jeremiah 23:6', 'Jeremiah', 23, 6, 'په هغه ورځو کښې به يهوداه بچ کړے شى او اِسرائيل به د سلامتۍ سره ژوند کوى. او دا هغه نوم دے چې په کوم سره به هغه ياديږى، مالِک خُدائ زمونږ خلاصونکے دے.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah23_verse_6.mp3', '', 1761754199, 1761754199),
(50528, 'Jeremiah 23:7', 'Jeremiah', 23, 7, 'مالِک خُدائ فرمائى چې، ”نو هغه ورځې راتلونکې دى چې خلق به نور داسې قسم نۀ خورى چې په هغه ژوندى خُدائ مو دې قسم وى چا چې بنى اِسرائيل د مِصر نه رابهر کړل،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah23_verse_7.mp3', '', 1761754199, 1761754199),
(50529, 'Jeremiah 23:8', 'Jeremiah', 23, 8, 'خو هغوئ به داسې وائى چې، قسم دے په هغه ژوندى مالِک خُدائ باندې چا چې د بنى اِسرائيل نسل د شمال او د نورو مُلکونو نه واپس راغونډ کړو کله چې هغۀ هغوئ تس نس کړى وُو. نو بيا به هغوئ په خپل مُلک کښې اوسيږى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah23_verse_8.mp3', '', 1761754199, 1761754199),
(50530, 'Jeremiah 23:9', 'Jeremiah', 23, 9, 'زما زړۀ د دروغژنو نبيانو په وجه مات شوے دے، او ټول هډُوکى مې په لړزان دى. زۀ لکه د هغه نشائى په شان شوے يم څوک چې په شرابو زيات نشه شوے وى، نو دغه شان زۀ د مالِک خُدائ او د مقدس کلام په وجه نشه يم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah23_verse_9.mp3', '', 1761754199, 1761754199),
(50531, 'Jeremiah 23:10', 'Jeremiah', 23, 10, 'دا مُلک د زناکارانو نه ډک دے، نو په دې وجه مالِک خُدائ ورباندې لعنت نازل کړے دے نو زمکه اوچه شوې ده او په للمه کښې شينکے اوچ شوے دے. نبيان په بدو لارو روان شوى دى او خپل طاقت په غلطه طريقه استعمالوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah23_verse_10.mp3', '', 1761754199, 1761754199),
(50532, 'Jeremiah 23:11', 'Jeremiah', 23, 11, 'مالِک خُدائ فرمائى چې، ”نبيان او اِمامان دواړه بې‌خُدايه کارونه کوى، تر دې چې ما په خپل کور کښې هم د دوئ بدعملۍ پېدا کړى دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah23_verse_11.mp3', '', 1761754199, 1761754199),
(50533, 'Jeremiah 23:12', 'Jeremiah', 23, 12, 'نو په دې وجه چې هغوئ چرته هم ځى د هغوئ پښې به ښوئيږى، او د تيارو خوا ته به بوتلے شى او هلته به هغوئ راوغورزيږى. زۀ به په هغوئ باندې د هغوئ د سزا په مقرر شوى وخت کښې افت نازل کړم.“ مالِک خُدائ داسې فرمائى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah23_verse_12.mp3', '', 1761754199, 1761754199),
(50534, 'Jeremiah 23:13', 'Jeremiah', 23, 13, '”ما د سامريه د نبيانو دا خراب کارونه وليدل چې کوم هغوئ د بعل په نوم پېشګوئې خلقو ته کوله او زما قوم بنى اِسرائيل يې بې‌لارې کړو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah23_verse_13.mp3', '', 1761754199, 1761754199),
(50535, 'Jeremiah 23:14', 'Jeremiah', 23, 14, 'خو ما د يروشلم په پېغمبرانو کښې د دې نه زيات خراب کار وليدلو، هغوئ زنا کوى او بې‌ايمانى کوى، او د بدعملو خلقو حوصله افزائى کوى، نو بيا يو هم د خپلو بد عملونو نه نۀ منع کيږى. هغوئ ټول زما دپاره د سدوم د خلقو په شان خراب دى، او د يروشلم خلق ما ته د عموره د خلقو په شان بد دى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah23_verse_14.mp3', '', 1761754199, 1761754199),
(50536, 'Jeremiah 23:15', 'Jeremiah', 23, 15, 'نو ځکه مالِک خُدائ ربُ الافواج د يروشلم د نبيانو په حقله داسې فرمائى، ”زۀ به هغوئ ته د خوړلو دپاره تريخ خوراک او د څښلو دپاره به ورله د زهرو اوبۀ ورکړم، ځکه چې د يروشلم د نبيانو په وجه، په ټول مُلک کښې بې‌دينى خوره شوې ده.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah23_verse_15.mp3', '', 1761754199, 1761754199),
(50537, 'Jeremiah 23:16', 'Jeremiah', 23, 16, 'مالِک خُدائ ربُ الافواج خپلو خلقو ته فرمائى چې، ”دا نبيان چې تاسو ته کومه پېشګوئې کوى د هغوئ خبرو ته غوږ مۀ نيسئ، هغوئ تاسو د دروغو په اُميدونو سره ډکوى. هغوئ تاسو ته د مالِک خُدائ پېغام نۀ درکوى خو صرف د خپل سوچ او زړۀ نه تاسو ته رويا پېش کوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah23_verse_16.mp3', '', 1761754199, 1761754199),
(50538, 'Jeremiah 23:17', 'Jeremiah', 23, 17, 'هغوئ هغه خلقو ته مسلسل خبرې کوى څوک چې ما سپک ګڼى، چې مالِک خُدائ فرمائى چې تاسو به په خير خيريت يئ. او هغوئ ټولو ته څوک چې د خپل سرکشه زړۀ تابعدارى کوى هغوئ وائى تاسو ته به هيڅ قسمه نقصان ونۀ رسيږى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah23_verse_17.mp3', '', 1761754199, 1761754199),
(50539, 'Jeremiah 23:18', 'Jeremiah', 23, 18, 'خو په هغوئ کښې کوم يو د مالِک خُدائ په حضور کښې ولاړ وو چې هغه څۀ يې ليدلى يا اورېدلى وى کوم چې هغۀ فرمائيلى دى؟ يو هم نه. چا هغۀ ته غوږ نيولے او چا د هغۀ آواز اورېدلے دے؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah23_verse_18.mp3', '', 1761754199, 1761754199),
(50540, 'Jeremiah 23:19', 'Jeremiah', 23, 19, 'ګورئ د مالِک خُدائ غضب لکه د طوفان په شان راروان دے، او د هغۀ غضب به د ډېر تېز طوفان په شان د بدعملو په سرونو باندې راتاو شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah23_verse_19.mp3', '', 1761754199, 1761754199),
(50541, 'Jeremiah 23:20', 'Jeremiah', 23, 20, 'او د مالِک خُدائ دا غضب به تر هغې پورې سوړ نۀ شى ترڅو پورې چې د هغۀ د زړۀ مقصد پوره شوے نۀ وى. په راتلونکو ورځو کښې به تاسو په دې ټولو باندې پوره پوهه شئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah23_verse_20.mp3', '', 1761754199, 1761754199),
(50542, 'Jeremiah 23:21', 'Jeremiah', 23, 21, '”ما دا نبيان نۀ دى لېږلى، خو هغوئ د خپل ځان نه د پېغام ورکولو دپاره په منډه شوى دى، ما د هغوئ سره خبرې نۀ دى کړې، خو هغوئ پېشګويانې وکړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah23_verse_21.mp3', '', 1761754199, 1761754199),
(50543, 'Jeremiah 23:22', 'Jeremiah', 23, 22, 'کۀ چرې هغوئ زما په حضور کښې ما سره ولاړ وے، نو هغوئ به بيا زما کلام خلقو ته اورولو او هغوئ به يې د خپلو شرارتونو او بدعملونو نه را اړول.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah23_verse_22.mp3', '', 1761754199, 1761754199),
(50544, 'Jeremiah 23:23', 'Jeremiah', 23, 23, 'مالِک خُدائ فرمائى چې، ”زۀ هغه خُدائ پاک يم چې هر چرته حاضر ناظر يم نه چې په يو ځائ کښې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah23_verse_23.mp3', '', 1761754199, 1761754199),
(50545, 'Jeremiah 23:24', 'Jeremiah', 23, 24, 'ولې داسې څوک شته چې زما نه خپل ځان چرته پټ کړى او زۀ هغه ونۀ وينم؟“ مالِک خُدائ فرمائى. ”ولې زۀ په هر ځائ زمکه او آسمان کښې نۀ يم څۀ؟“ مالِک خُدائ فرمائى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah23_verse_24.mp3', '', 1761754199, 1761754199),
(50546, 'Jeremiah 23:25', 'Jeremiah', 23, 25, '”ما هغه هر څۀ واورېدل څۀ چې دې پېغمبرانو خلقو ته وفرمائيل څوک چې زما په نوم دروغ وائى او خلقو ته وائى چې، ما خوب وليدو. په خوب کښې په ما الهام وشو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah23_verse_25.mp3', '', 1761754199, 1761754199),
(50547, 'Jeremiah 23:26', 'Jeremiah', 23, 26, 'دا خبرې به ترڅو پورې د دې دروغژنو پېغمبرانو په زړونو کښې راځى، څوک چې د خپلو سوچونو پېغامونه خلقو ته بيانوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah23_verse_26.mp3', '', 1761754199, 1761754199),
(50548, 'Jeremiah 23:27', 'Jeremiah', 23, 27, 'د هغوئ خيال دا دے چې کوم خوبونه چې دوئ په خپلو کښې يو بل ته بيانوى نو د دې په وجه به زما خلق زما نوم هېر کړى، لکه څنګه چې پخوا د دوئ پلار نيکۀ زما نوم هېر کړے وو او د بعل بُت عبادت يې وکړو.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah23_verse_27.mp3', '', 1761754199, 1761754199),
(50549, 'Jeremiah 23:28', 'Jeremiah', 23, 28, 'مالِک خُدائ فرمائى چې، ”کوم پېغمبر چې خوب ليدلے دے هغه دې بې‌شکه خپل خوب بيان کړى، خو چې په چا زما کلام نازل شوے دے هغه دې په وفادارۍ سره کلام خلقو ته واوروى. تش بوس د غنمو برابر دى څۀ؟“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah23_verse_28.mp3', '', 1761754199, 1761754199),
(50550, 'Jeremiah 23:29', 'Jeremiah', 23, 29, 'مالِک خُدائ فرمائى چې، ”آيا زما پېغام د اور په شان نۀ دے څۀ، او زما پېغام د څټک په شان نۀ دے څۀ چې ګټ ټوټه ټوټه کوى؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah23_verse_29.mp3', '', 1761754199, 1761754199),
(50551, 'Jeremiah 23:30', 'Jeremiah', 23, 30, 'نو ځکه زۀ د هغه پېغمبرانو خِلاف يم څوک چې د يو بل نه خبرې نقل کوى او بيا خلقو ته وائى چې دا کلام زما د طرفه دے.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah23_verse_30.mp3', '', 1761754199, 1761754199),
(50552, 'Jeremiah 23:31', 'Jeremiah', 23, 31, 'مالِک خُدائ فرمائى چې، ”زۀ د هغه پېغمبرانو خِلاف هم يم چا چې خپله خولۀ پرانستى وى او د خپل ځان نه لګيا وى خبرې کوى او بيا وائى چې مالِک خُدائ داسې فرمائى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah23_verse_31.mp3', '', 1761754199, 1761754199),
(50553, 'Jeremiah 23:32', 'Jeremiah', 23, 32, 'په حقيقت کښې زۀ د هغوئ خلاف يم،“ مالِک خُدائ دا بيان کوى، ”څوک چې د دروغو خوبونه جوړوى او زما خلقو ته هغه بيانوى، او هغوئ په خپلو بې‌حسابه دروغو سره زما خلق بې‌لارې کوى، حال دا چې نۀ ما هغوئ لېږلى دى او نۀ مې مقرر کړى دى. او هغوئ د خلقو د فائدې هيڅ خبرې نۀ کوى.“ مالِک خُدائ دا بيان کوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah23_verse_32.mp3', '', 1761754199, 1761754199),
(50554, 'Jeremiah 23:33', 'Jeremiah', 23, 33, '”يرمياه، کله چې د دې خلقو نه عام کس يا پېغمبر يا اِمام ستا نه تپوس وکړى چې، تا سره د مالِک خُدائ نه کوم دروند پيټے شته څۀ؟ نو تۀ په جواب کښې ورته ووايه، نو هغه دروند پيټے هم تۀ يې، مالِک خُدائ فرمائى، زۀ به تا وغورزوم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah23_verse_33.mp3', '', 1761754199, 1761754199),
(50555, 'Jeremiah 23:34', 'Jeremiah', 23, 34, 'کۀ چرې يو پېغمبر، يا اِمام يا بل څوک دا دعوىٰ وکړى چې، ”دا د مالِک خُدائ دروند پيټے دے،“ زۀ به دۀ له او د دۀ خاندان له سزا ورکړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah23_verse_34.mp3', '', 1761754199, 1761754199),
(50556, 'Jeremiah 23:35', 'Jeremiah', 23, 35, 'نو بيا دې دا هر يو کس په تاسو کښې د يو بل نه او د خپلو دوستانو او خپلوانو نه تپوس کوى چې، ”مالِک خُدائ په جواب کښې څۀ فرمائيلى دى؟“ او يا دا چې، ”مالِک خُدائ کومه خبره کړې ده؟“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah23_verse_35.mp3', '', 1761754199, 1761754199),
(50557, 'Jeremiah 23:36', 'Jeremiah', 23, 36, 'خو نور به تۀ بيا کله هم دا ونۀ وائې چې، ”د مالِک خُدائ پېغام يو دروند پيټے دے،“ ځکه چې د هر سړى خپله خبره د هغۀ پېغام وګرځېدو نو تاسو بيا دغه شان د ژوندى مالِک خُدائ، ربُ الافواج خُدائ زمونږ د خُدائ پاک پېغام ته تعبير ورکوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah23_verse_36.mp3', '', 1761754199, 1761754199),
(50558, 'Jeremiah 23:37', 'Jeremiah', 23, 37, 'تاسو پېغمبرانو ته داسې ووايئ چې، ”مالِک خُدائ تاسو له څۀ جواب درکړو؟ مالِک خُدائ څۀ فرمائيلى دى؟“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah23_verse_37.mp3', '', 1761754199, 1761754199),
(50559, 'Jeremiah 23:38', 'Jeremiah', 23, 38, 'او کۀ بيا هم تاسو دا دعوىٰ کوئ چې، ”دا د مالِک خُدائ نه دروند پيټے دے،“ نو مالِک خُدائ بيا داسې فرمائى چې، ”تاسو خبرې خو کوئ چې دا د مالِک خُدائ نه دروند پيټے دے، اګر چې ما درته فرمائيلى وُو چې داسې خبرې مۀ کوئ چې دا د مالِک خُدائ د طرف نه دروند پيټے دے،“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah23_verse_38.mp3', '', 1761754199, 1761754199),
(50560, 'Jeremiah 23:39', 'Jeremiah', 23, 39, '‎‏نو په دې وجه به زۀ تاسو په يقين سره هېر کړم او سره د هغه ښاره کوم چې ما تاسو او ستاسو پلار نيکۀ له ورکړو د خپل حضور نه لرې وشړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah23_verse_39.mp3', '', 1761754199, 1761754199),
(50561, 'Jeremiah 23:40', 'Jeremiah', 23, 40, 'زۀ به په تاسو باندې نۀ ختمېدونکے لعنت او ابدى شرم نازل کړم چې هيڅکله به هېرولے نۀ شى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah23_verse_40.mp3', '', 1761754199, 1761754199),
(50562, 'Jeremiah 14:1', 'Jeremiah', 14, 1, 'د اوچ کالۍ په حقله په يرمياه د مالِک خُدائ کلام نازل شو،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah14_verse_1.mp3', '', 1761754199, 1761754199),
(50563, 'Jeremiah 14:2', 'Jeremiah', 14, 2, '”يهوداه وير کوى، ښارونه يې لکه د اوچو شوو بوټو په شان غمژن دى، ټول خلق يې د غم په وجه په زمکه ناست دى او د يروشلم نه چغې او سورې راپورته کيږى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah14_verse_2.mp3', '', 1761754199, 1761754199),
(50564, 'Jeremiah 14:3', 'Jeremiah', 14, 3, 'مالداره خلق خپل نوکران د اوبو دپاره کُوهيانو ته لېږى، خو ټولې چينې کُوهيان اوچ شوى وى او د ګوټ اوبو درک هم نۀ لګى. نوکران په ډيرې مايوسۍ او خفګان د تشو منګو سره راواپس کيږى او خپل سرونه يې د پرېشانۍ په وجه پټ کړى وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah14_verse_3.mp3', '', 1761754199, 1761754199),
(50565, 'Jeremiah 14:4', 'Jeremiah', 14, 4, 'زمکه د خوشکۍ او د باران نۀ ورېدلو په وجه چاؤدلې ده، زميداران پرېشانه دى، او هغوئ هم خپل مخونه پټ کړى دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah14_verse_4.mp3', '', 1761754199, 1761754199),
(50566, 'Jeremiah 14:5', 'Jeremiah', 14, 5, 'په پټو کښې د خوراک دپاره د ګياه د نشتوالى په وجه هوسۍ هم خپل تازه پېدا شوى بچى هم داسې په ډاګه پرېښى دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah14_verse_5.mp3', '', 1761754199, 1761754199),
(50567, 'Jeremiah 14:6', 'Jeremiah', 14, 6, 'ځنګلى خرونه هم د خوشکو غونډو په سرونو ودريږى او د ګيدړانو په شان چغې وهى او د خوراک د نشتوالى په وجه يې نظر کار پرېښے دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah14_verse_6.mp3', '', 1761754199, 1761754199),
(50568, 'Jeremiah 14:7', 'Jeremiah', 14, 7, 'زما خلق ما ته فرياد کوى او وائى چې، زمونږ ګناهونه زمونږ خِلاف ګواهى ورکوى، خو اے مالِکه خُدايه، د خپل نوم د خاطره دې زمونږ مدد وکړه. مونږ ستا نه په څو ځله اوړېدلى يُو، او ستا خِلاف مو ګناه کړې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah14_verse_7.mp3', '', 1761754199, 1761754199),
(50569, 'Jeremiah 14:8', 'Jeremiah', 14, 8, 'اے مالِکه خُدايه صرف تۀ د بنى اِسرائيلو اُميد يې، او د تکليف په وخت کښې زمونږ خلاصونکے يې. نو بيا ولې تۀ لکه د يو مسافر په شان يې چې زمونږ په مُلک کښې صرف يوه شپه تېره کړى او بيا ځى؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah14_verse_8.mp3', '', 1761754199, 1761754199),
(50570, 'Jeremiah 14:9', 'Jeremiah', 14, 9, 'تۀ ولې د هغه چا په شان يې چې ګنګس وى، او لکه د داسې فوجى په شان شوے يې چې څوک بچ کولے نۀ شى؟ اے مالِکه خُدايه، تۀ مونږ سره يې، او مونږ ستا نوم پورې تړلے شوى يُو، نو اوس مونږ مۀ پرېږده.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah14_verse_9.mp3', '', 1761754199, 1761754199),
(50571, 'Jeremiah 14:10', 'Jeremiah', 14, 10, 'نو مالِک خُدائ د دې خلقو په حقله فرمائى، ”د دوئ ډېر زيات دا خوښېدل چې فضول وګرځى او زما نه واوړى او په خپل ځان يې قابو نۀ وُو. نو ځکه زۀ د دوئ نه راضى نۀ يم. او د دوئ ګناهونه به راته ياد وى، او سزا به ورله ورکړم.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah14_verse_10.mp3', '', 1761754199, 1761754199),
(50572, 'Jeremiah 14:11', 'Jeremiah', 14, 11, 'مالِک خُدائ ما ته وفرمائيل، ”نور د دې قوم د خير دپاره ما ته سوال مۀ کوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah14_verse_11.mp3', '', 1761754199, 1761754199),
(50573, 'Jeremiah 14:12', 'Jeremiah', 14, 12, 'تر دې کۀ هغوئ روژه هم ونيسى، نو زۀ به د هغوئ فرياد ته غوږ نۀ نيسم. او کۀ چرې هغوئ ما ته سوزېدونکې او د غلې نذرانې هم پېش کړى، نو زۀ به هغه نۀ قبلوم. بلکې هغوئ به په جنګ، قحط او وبا باندې مړۀ کړم.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah14_verse_12.mp3', '', 1761754199, 1761754199),
(50574, 'Jeremiah 14:13', 'Jeremiah', 14, 13, 'نو بيا ما ووئيل، ”اے قادر مطلق خُدايه، د هغوئ پېغمبران ورته وائى هر څۀ ټيک دى جنګ او قحط به نۀ راځى. مالِک خُدائ به په حقيقت کښې په تاسو امن راولېږى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah14_verse_13.mp3', '', 1761754199, 1761754199),
(50575, 'Jeremiah 14:14', 'Jeremiah', 14, 14, 'نو بيا مالِک خُدائ ما ته وفرمائيل چې، ”زما په نوم دا پېغمبران د دروغو نبوت کوى. د هغوئ پېغام زما له طرف نه نۀ دے او نۀ ما هغوئ ته حکم کړے دے چې تاسو دا پېغام خلقو له ورکړئ. هغوئ دروغژنې روياګانې، او فضول فالونه او د خپلو دروغژنو خيالونو پېشګويانې کوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah14_verse_14.mp3', '', 1761754199, 1761754199),
(50576, 'Jeremiah 14:15', 'Jeremiah', 14, 15, 'نو ځکه مالِک خُدائ فرمائى چې کوم پېغمبران چې زما په نوم د دروغو نبوت کوى او خلقو ته وائى چې نۀ به جنګ راځى او نۀ به قحط، چا ته چې ما پېغام نۀ دے ورکړے نو هم دوئ به زۀ په جنګ او قحط باندې هلاک کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah14_verse_15.mp3', '', 1761754199, 1761754199),
(50577, 'Jeremiah 14:16', 'Jeremiah', 14, 16, 'کومو خلقو ته چې هغوئ دا پېشګويانې کوى نو د هغوئ لاشونه به د يروشلم په لارو کوڅو کښې د جنګ او قحط په وجه وغورزولے شى. څوک به نۀ وى چې هغوئ او د هغوئ ښځې، زامن، لوڼه ښخ کړى. او زۀ به په هغوئ هغه افت نازل کړم د کوم چې لائق دى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah14_verse_16.mp3', '', 1761754199, 1761754199),
(50578, 'Jeremiah 14:17', 'Jeremiah', 14, 17, 'مالِک خُدائ ما ته وفرمائيل چې، ”يرمياه هغوئ ته دا ووايه، زما د سترګو نه شپه او ورځ اوښکې بهيږى، زما ژړا نۀ ودريږى، ځکه چې زما قوم چې په ما لکه د لور په شان ګران دے سخت زخمى شوے دے او زيات ژوبل شوے دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah14_verse_17.mp3', '', 1761754199, 1761754199),
(50579, 'Jeremiah 14:18', 'Jeremiah', 14, 18, 'کله چې زۀ بهر مېدانونو ته لاړ شم، نو زۀ هغوئ وينم څوک چې په جنګ کښې په تُورو مړۀ شوى دى، او کۀ زۀ دننه د ښار کوڅو ته لاړ شم، نو زۀ هغه خلق ګورم چې د قحط په وجه مړۀ شوى دى. پېغمبران او اِمامان دواړه خپل کارونه جارى ساتى، خو هغوئ په دې نۀ پوهيږى چې څۀ کوى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah14_verse_18.mp3', '', 1761754199, 1761754199),
(50580, 'Jeremiah 14:19', 'Jeremiah', 14, 19, 'اے مالِکه خُدايه، تا يهوداه بلکل رد کړے دے څۀ؟ آيا تۀ د صيون د خلقو نه نفرت کوې څۀ؟ ولې تا مونږ دومره سخت زخمى کړى يُو چې د رغېدو ټول اُميدونه مو ختم شُو څۀ؟ مونږ د خير اُميد لرلو خو مونږ ته خير مِلاو نۀ شو، مونږ د علاج په طمع وُو خو د شفا په ځائ په مونږ يره راغله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah14_verse_19.mp3', '', 1761754199, 1761754199),
(50581, 'Jeremiah 14:20', 'Jeremiah', 14, 20, 'اے مالِکه خُدايه، مونږ ستا خِلاف بدکارونه کړى دى، مونږ د خپلو بدو کارونو او د خپل پلار نيکۀ د بدو کارونو اِقرار کوُو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah14_verse_20.mp3', '', 1761754199, 1761754199),
(50582, 'Jeremiah 14:21', 'Jeremiah', 14, 21, 'د خپل نوم د خاطره دې مونږ مۀ پرېږده، او خپل جلالى تخت دې مۀ سپکوه. خپل لوظ دې راپه ياد کړه کوم چې تا مونږ سره کړے دے او هغه مۀ ماتوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah14_verse_21.mp3', '', 1761754199, 1761754199),
(50583, 'Jeremiah 14:22', 'Jeremiah', 14, 22, 'آيا د نورو قومونو د بُتانو فضول معبودان باران کولے شى څۀ؟ آيا آسمان په خپله باران ورولے شى څۀ؟ نه، بلکې دا تۀ يې، اے مالِکه خُدايه، زمونږ پاکه خُدايه. نو د دې دپاره زمونږ توکل په تا دے، ځکه چې تۀ هغه ذات يې څوک چې دا هر څۀ کوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah14_verse_22.mp3', '', 1761754199, 1761754199),
(50584, 'Psalms 109:1', 'Psalms', 109, 1, 'ای خدایه چې ستا ثنا وایمه مه پاتې کېږه خاموش', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms109_verse_1.mp3', '', 1761754199, 1761754199),
(50585, 'Psalms 109:2', 'Psalms', 109, 2, 'بدکارانو او دروغجنو خلکو خولې خلاصې کړې دي په ما پسې زما په هکله هغوی دروغ وایي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms109_verse_2.mp3', '', 1761754199, 1761754199),
(50586, 'Psalms 109:3', 'Psalms', 109, 3, 'رانه چاپېر دي هغوی او راته کوي خبرې له نفرتونو ډکې او بې‌سببه کوي جنګ راسره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms109_verse_3.mp3', '', 1761754199, 1761754199),
(50587, 'Psalms 109:4', 'Psalms', 109, 4, 'زما د مینې په بدل کې لګوي په ما تورونه خو زه د هغوی دپاره دعا کومه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms109_verse_4.mp3', '', 1761754199, 1761754199),
